def unescape_controls(text):
    result=[]
    i=0
    mapping={'n':'\n','t':'\t','\\':'\\'}
    while i<len(text):
        if text[i]=='\\':
            i+=1
            if i==len(text) or text[i] not in mapping:
                raise ValueError('invalid escape')
            result.append(mapping[text[i]])
        else:
            result.append(text[i])
        i+=1
    return ''.join(result)
